{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "SRT2104, measured in fasted healthy subjects with an IV 14C-microdose reference, had absolute oral bioavailability of 13.8% (range 2–27%), directly below the 20% threshold; this is the closest endpoint/condition match and strongly supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Revefenacin has absolute oral bioavailability <3% in healthy adults, showing that a complex drug-like molecule with multiple polar and aromatic groups can have very poor oral absorption; supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lopinavir, a peptidomimetic protease inhibitor sharing the hydroxyethylene core and multiple aromatic/amide features with the query, has low oral bioavailability due to CYP3A4 metabolism and P-gp efflux; supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alvimopan has approximately 6% systemic bioavailability in adult patients, another human low-F example for an orally dosed drug; supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "CDP323 showed 14% absolute oral bioavailability in humans, the highest among the retrieved analogues but still below the 20% threshold; supports low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability below 20% (mostly <15%, many <5%), and the query's large peptidomimetic structure with multiple amides, H-bond donors, and likely efflux/metabolism liabilities is consistent with low oral F. Therefore predict low.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "All retrieved analogues are low-F compounds; no high-F comparator was available to calibrate the upper range.",
    "Exact human F for the query is unknown; the threshold decision relies on transferable low-F evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

